save(84,dict(paragraphs=["Lipika Das’s Odia poems in Kabita Live bring private unease into conversation with the wider world. ‘ଖଵର ପୃଷ୍ଠାରେ ସମୟ’ moves from a storm-damaged garden and rain at a balcony to stories of poverty, discrimination and war. Its images suggest how public suffering can enter the most solitary moments of reading and reflection.","In ‘କୁହେଳି’, questions about light, discovery and identity unfold through the moon, a burning river, butterflies and the sea. Scientific exploration stands beside the difficulty of meeting ordinary human needs. These poems make their argument through shifting images and unanswered questions, inviting the reader to remain with uncertainty."],sources=[],status='source_limited_local_draft',identity_match='Two Odia contributions and local writer ID establish the profile; empty captured biography provides no identity bridge to external scholars or book authors.',poems_read=[dict(id=664,title='ଖଵର ପୃଷ୍ଠାରେ ସମୟ',basis='Full text read: damaged garden, rain/solitude, African stories, poverty/discrimination and newspaper war reports.'),dict(id=93,title='କୁହେଳି',basis='Full text read: moon scientists, light, pain, river fire unable to cook rice, identity questions, shells/sea.')],limitations=['Lipika Das/Dash has multiple public namesakes; no education, employment, awards or book claims added.','Sahitya Akademi identifies an Odia poet Lipika Dash, but no matching poem or independent local detail establishes this profile as that writer.','No personal mental-health or political-belief inference made from speakers or imagery.'],research_leads=[dict(url='https://www.sahitya-akademi.gov.in/e-newsletter/may-june_2017_Newsletter.pdf',finding='Indexed Asmita event lists Odia poet Lipika Dash; useful candidate, insufficient identity bridge.'),dict(url='https://ritikart.com/products/akharka-khara-by-lipika-das',finding='Indexed Odia poetry book by same name; no local title match; excluded pending confirmation.'),dict(url='https://wls.sav.sk/wp-content/uploads/WLS_2_2022_complete.pdf',finding='IIIT Bhubaneswar scholar Lipika Das appears in indexed academic article; not linked to this poet.'),dict(query='ଲିପିକା ଦାସ କୁହେଳି; ଲିପିକା ଦାସ ଖବର',finding='No useful exact-poem match found.')],next_action='Author/editor confirm biographical identity and any bibliography; independent interpretation review.'))
